66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
75	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
76	     */
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
79	
80	    /**
81	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
82	     * new owner's id, customerCode, registrationDate and membershipLevel.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    /**
87	     * Common street-type abbreviations expanded during address normalization, keyed by the
88	     * upper-cased abbreviation.
89	     */
90	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
91	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
92	
93	    /**
94	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
95	     * city already holds this many owners.
96	     */
97	    private static final int CITY_CAPACITY = 50;
98	
99	    /**
100	     * Maximum number of owners that may be created on a single day. A create is rejected once this
101	     * many owners already carry the current day as their {@code registrationDate}.
102	     */
103	    private static final int DAILY_OWNER_LIMIT = 100;
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        validateRequiredFields(ownerFieldsDto);
152	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
156	        LocalDate effectiveDate = owner.getRegistrationDate() == null
157	            ? LocalDate.now()
158	            : owner.getRegistrationDate();
159	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
160	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
161	        rejectWhenCityAtCapacity(owner.getCity());
162	        applyHousehold(owner);
163	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
164	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
165	        rejectDuplicateIdentity(owner);
166	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
167	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
168	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
169	        this.clinicService.saveOwner(owner);
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
173	            ownerDto.getMembershipLevel());
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    /**
180	     * Builds the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
181	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three letters
182	     * of the owner's last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more
183	     * than the number of owners already in that city (e.g. {@code MAD-SMI-0007}).
184	     *
185	     * @param city     the owner's city
186	     * @param lastName the owner's last name
187	     * @return the assigned customer code
188	     */
189	    private String nextCustomerCode(String city, String lastName) {
190	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
191	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
192	        int sequence = (int) this.clinicService.findAllOwners().stream()
193	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
194	            .count() + 1;
195	        return String.format("%s-%s-%04d", city3, last3, sequence);
196	    }
197	
198	    /**
199	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
200	     * last two digits of the registrationDate year, zero-padded (e.g. {@code MAD-SMI-0007-M26}).
201	     *
202	     * @param customerCode     the owner's assigned customer code
203	     * @param registrationDate the owner's registration date
204	     * @return the assigned membership number
205	     */
206	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
207	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
208	    }
209	
210	    /**
211	     * Counts the existing owners that already share the given firstName and lastName, compared
212	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
213	     * the owners that pre-existed this create.
214	     *
215	     * @param firstName the new owner's first name
216	     * @param lastName  the new owner's last name
217	     * @return the number of existing namesakes
218	     */
219	    private int countNamesakes(String firstName, String lastName) {
220	        return (int) this.clinicService.findAllOwners().stream()
221	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
222	                && equalsIgnoreCase(existing.getLastName(), lastName))
223	            .count();
224	    }
225	
226	    /**
227	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
228	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
229	     * customer-code sequence is derived.
230	     *
231	     * @param city the new owner's city
232	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
233	     */
234	    private void rejectWhenCityAtCapacity(String city) {
235	        long count = this.clinicService.findAllOwners().stream()
236	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
237	            .count();
238	        if (count >= CITY_CAPACITY) {
239	            throw new CityAtCapacityException(city);
240	        }
241	    }
242	
243	    /**
244	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
245	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
246	     * business-day registration date, so the limit is enforced per business day and weekend
247	     * requests count against the Monday they roll forward to.
248	     *
249	     * @param registrationDate the owner's adjusted (business-day) registration date
250	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
251	     *                                  registration date
252	     */
253	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
254	        long count = this.clinicService.findAllOwners().stream()
255	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
256	            .count();
257	        if (count >= DAILY_OWNER_LIMIT) {
258	            throw new DailyOwnerLimitException(registrationDate);
259	        }
260	    }
261	
262	    /**
263	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
264	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
265	     * effective registration date (whether supplied in the request or defaulted to the server date)
266	     * so a weekend value never persists as an owner's {@code registrationDate}.
267	     *
268	     * @param date the effective registration date
269	     * @return the same date when it is a weekday, otherwise the next Monday
270	     */
271	    private LocalDate toBusinessDay(LocalDate date) {
272	        return switch (date.getDayOfWeek()) {
273	            case SATURDAY -> date.plusDays(2);
274	            case SUNDAY -> date.plusDays(1);
275	            default -> date;
276	        };
277	    }
278	
279	    private boolean equalsIgnoreCase(String a, String b) {
280	        return a == null ? b == null : a.equalsIgnoreCase(b);
281	    }
282	
283	    /**
284	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
285	     * offending field so the client learns about all of them at once.
286	     *
287	     * @param ownerFieldsDto the submitted owner fields
288	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
289	     *                                     missing or blank
290	     */
291	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
292	        List<String> errors = new ArrayList<>();
293	        if (isBlank(ownerFieldsDto.getFirstName())) {
294	            errors.add("firstName");
295	        }
296	        if (isBlank(ownerFieldsDto.getLastName())) {
297	            errors.add("lastName");
298	        }
299	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
300	            errors.add("address");
301	        }
302	        if (isBlank(ownerFieldsDto.getCity())) {
303	            errors.add("city");
304	        }
305	        if (isBlank(ownerFieldsDto.getTelephone())) {
306	            errors.add("telephone");
307	        }
308	        if (!errors.isEmpty()) {
309	            throw new MissingOwnerFieldsException(errors);
310	        }
311	    }
312	
313	    private boolean isBlank(String value) {
314	        return value == null || value.isBlank();
315	    }
316	
317	    /**
318	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
319	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
320	     */
321	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
322	        "NSW", new int[] {2000, 2099},
323	        "VIC", new int[] {3000, 3099},
324	        "QLD", new int[] {4000, 4099});
325	
326	    /**
327	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
328	     * is optional and accepted, keeping the create contract backward-compatible. When present the
329	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
330	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
331	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
332	     *
333	     * @param postcode the raw postcode value as submitted, may be {@code null}
334	     * @param city     the owner's city, used to resolve the region whose range applies
335	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
336	     *                                  the city's region
337	     */
338	    private void validatePostcode(String postcode, String city) {
339	        if (isBlank(postcode)) {
340	            return;
341	        }
342	        if (!postcode.matches("[0-9]{4}")) {
343	            throw new InvalidPostcodeException(postcode, city);
344	        }
345	        String region = region(city);
346	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
347	        if (range != null) {
348	            int value = Integer.parseInt(postcode);
349	            if (value < range[0] || value > range[1]) {
350	                throw new InvalidPostcodeException(postcode, city);
351	            }
352	        }
353	    }
354	
355	    /**
356	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
357	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
358	     *
359	     * @param city the owner's city
360	     * @return the region code, or {@code null} when the city has no known region
361	     */
362	    private String region(String city) {
363	        if (city == null) {
364	            return null;
365	        }
366	        return switch (city) {
367	            case "Sydney" -> "NSW";
368	            case "Melbourne" -> "VIC";
369	            case "Brisbane" -> "QLD";
370	            default -> null;
371	        };
372	    }
373	
374	    /**
375	     * The number of national (subscriber) digits an E.164 number must carry for a given country
376	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
377	     * national digits and the North American Numbering Plan ('+1') requires 10.
378	     */
379	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
380	        Map.of("61", 9, "1", 10);
381	
382	    /**
383	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
384	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
385	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
386	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
387	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
388	     *
389	     * @param telephone the raw telephone value as submitted
390	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
391	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
392	     *                                   national-number length is wrong for its country code
393	     */
394	    private String normalizeTelephone(String telephone) {
395	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
396	        String nationalSignificantNumber;
397	        if (cleaned.startsWith("+")) {
398	            nationalSignificantNumber = cleaned.substring(1);
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            nationalSignificantNumber = "61" + national;
402	        }
403	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
404	            throw new InvalidTelephoneException(telephone);
405	        }
406	        validateNationalNumberLength(nationalSignificantNumber, telephone);
407	        return "+" + nationalSignificantNumber;
408	    }
409	
410	    /**
411	     * Validates the national-number length of an E.164 number against its country calling code. The
412	     * significant number is a country code immediately followed by the national digits; for each
413	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
414	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
415	     * left unchecked.
416	     *
417	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
418	     * @param rejectedValue             the raw telephone value, reported on rejection
419	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
420	     */
421	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
422	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
423	            String countryCode = rule.getKey();
424	            if (nationalSignificantNumber.startsWith(countryCode)) {
425	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
426	                if (nationalDigits != rule.getValue()) {
427	                    throw new InvalidTelephoneException(rejectedValue);
428	                }
429	                return;
430	            }
431	        }
432	    }
433	
434	    /**
435	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
436	     * value is treated as absent and returns {@code null}); when present the value must be a
437	     * syntactically valid address, and is stored and returned lower-cased.
438	     *
439	     * @param email the raw email value as submitted, may be {@code null}
440	     * @return the lower-cased email, or {@code null} when none was supplied
441	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
442	     */
443	    private String normalizeEmail(String email) {
444	        if (email == null || email.isBlank()) {
445	            return null;
446	        }
447	        String normalized = email.trim().toLowerCase();
448	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
449	            throw new InvalidEmailException(email);
450	        }
451	        return normalized;
452	    }
453	
454	    /**
455	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
456	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
457	     * key is the normalized telephone, email and householdId joined together, this one check
458	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
459	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
460	     * with different telephones have different keys and are both allowed.
461	     *
462	     * @param owner the owner being created, with its normalized telephone, email and householdId
463	     *              already applied
464	     * @throws DuplicateIdentityException if another owner already has the same identityKey
465	     */
466	    private void rejectDuplicateIdentity(Owner owner) {
467	        String identityKey = identityKey(owner);
468	        boolean inUse = this.clinicService.findAllOwners().stream()
469	            .map(this::identityKey)
470	            .anyMatch(identityKey::equals);
471	        if (inUse) {
472	            throw new DuplicateIdentityException(identityKey);
473	        }
474	    }
475	
476	    /**
477	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
478	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
479	     * duplicate decision is made by comparing whole identityKeys.
480	     *
481	     * @param owner the owner whose identityKey to derive
482	     * @return the derived identityKey
483	     */
484	    private String identityKey(Owner owner) {
485	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
486	        String email = owner.getEmail() == null ? "" : owner.getEmail();
487	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
488	        return telephone + "|" + email + "|" + householdId;
489	    }
490	
491	    /**
492	     * Applies the household rule to an owner being created. An owner belongs to the same household
493	     * as an existing owner when their lastName and address both match (compared case-insensitively
494	     * with runs of whitespace collapsed to a single space).
495	     *
496	     * <p>When no such existing owner exists there is nothing to do. Otherwise the new owner and
497	     * every existing owner in the household are assigned the same stable
498	     * {@link #householdId(String, String) householdId}. The household itself is no longer a
499	     * rejection: duplicate detection is now decided solely by the whole {@code identityKey}, of
500	     * which the householdId is one segment, so two members of the same household with different
501	     * telephones have different keys and are both allowed.
502	     *
503	     * @param owner the owner being created
504	     */
505	    private void applyHousehold(Owner owner) {
506	        String lastNameKey = toHouseholdKey(owner.getLastName());
507	        String addressKey = toHouseholdKey(owner.getAddress());
508	        List<Owner> household = this.clinicService.findAllOwners().stream()
509	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
510	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
511	            .toList();
512	        if (household.isEmpty()) {
513	            return;
514	        }
515	        String householdId = householdId(lastNameKey, addressKey);
516	        owner.setHouseholdId(householdId);
517	        for (Owner existing : household) {
518	            if (!householdId.equals(existing.getHouseholdId())) {
519	                existing.setHouseholdId(householdId);
520	                this.clinicService.saveOwner(existing);
521	            }
522	        }
523	    }
524	
525	    /**
526	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
527	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
528	     * lastName and address keys. Being a pure function of the household, every owner in it derives
529	     * the same value regardless of creation order.
530	     *
531	     * @param lastNameKey the normalized household lastName key
532	     * @param addressKey  the normalized household address key
533	     * @return the household identifier
534	     */
535	    private String householdId(String lastNameKey, String addressKey) {
536	        try {
537	            byte[] digest = MessageDigest.getInstance("SHA-256")
538	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
539	            StringBuilder hex = new StringBuilder(digest.length * 2);
540	            for (byte b : digest) {
541	                hex.append(String.format("%02x", b));
542	            }
