86	        }
87	        String city = owner.getCity();
88	        if (city == null) {
89	            return "UNKNOWN";
90	        }
91	        return switch (city) {
92	            case "Sydney" -> "NSW";
93	            case "Melbourne" -> "VIC";
94	            case "Brisbane" -> "QLD";
95	            default -> "UNKNOWN";
