104	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
105	            return null;
106	        }
107	        int value = Integer.parseInt(postcode);
108	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
109	            int[] range = entry.getValue();
110	            if (value >= range[0] && value <= range[1]) {
111	                return entry.getKey();
112	            }
113	        }
114	        return null;
115	    }
